import { InterviewQuestion } from '../models/interview-question.model';

const ANSWER_RULES: readonly [RegExp, string][] = [
  [/^What is Spring Boot\?$/i, 'Spring Boot is a Java framework built on Spring. It provides sensible defaults, starter dependencies, auto-configuration, and an embedded server so you can create production-ready applications with less setup.'],
  [/different from the Spring Framework/i, 'Spring Framework provides the core features such as dependency injection and MVC. Spring Boot adds conventions, auto-configuration, starter dependencies, and embedded-server support on top of Spring, so a project needs less manual configuration.'],
  [/main advantages of Spring Boot/i, 'The main advantages are faster development, less XML or manual configuration, embedded servers, consistent dependency management, easy testing, and production features such as health checks and metrics.'],
  [/problems does Spring Boot solve/i, 'Spring Boot reduces repetitive project setup, dependency-version conflicts, server configuration, and boilerplate integration code. It lets developers focus more on business functionality.'],
  [/convention over configuration/i, 'Convention over configuration means the framework chooses sensible defaults based on common project conventions. You only configure the parts that differ from those defaults.'],
  [/embedded server/i, 'An embedded server is a web server packaged inside the application. The application can start with a Java command instead of requiring a separately installed server and manually deployed WAR file.'],
  [/Which embedded servers/i, 'Spring Boot commonly supports Tomcat, Jetty, and Undertow for servlet-based applications. Spring WebFlux applications commonly use Reactor Netty, with other servers available through supported dependencies.'],
  [/SpringApplication\.run/i, 'SpringApplication.run() creates and refreshes the ApplicationContext, loads configuration, performs component scanning and auto-configuration, starts the embedded server when needed, and publishes startup events.'],
  [/internally when a Spring Boot application starts/i, 'Spring Boot creates the environment, prepares the ApplicationContext, discovers configuration and components, applies conditional auto-configuration, creates beans, runs startup callbacks, and starts the web server.'],
  [/role of the ApplicationContext/i, 'ApplicationContext is Spring’s IoC container. It creates and manages beans, resolves dependencies, provides configuration, publishes events, and controls the application lifecycle.'],
  [/auto-configuration/i, 'Auto-configuration configures common Spring components automatically when the required classes are present and the application has not already supplied its own bean. It is conditional, so it backs away when your configuration takes control.'],
  [/EnableAutoConfiguration/i, '@EnableAutoConfiguration tells Spring Boot to consider its auto-configuration classes. @SpringBootApplication already includes this annotation, so it is rarely written separately.'],
  [/conditional annotations/i, 'Conditional annotations apply configuration only when a condition is true. They allow Boot to check classes, properties, beans, resources, or application type before creating a bean.'],
  [/ConditionalOnClass/i, '@ConditionalOnClass activates a configuration only when a specified class is available on the classpath. It prevents configuration from being applied when its library is not installed.'],
  [/ConditionalOnMissingBean/i, '@ConditionalOnMissingBean creates a default bean only when the application has not already defined a matching bean. This lets developers replace Boot’s default safely.'],
  [/exclude a specific auto-configuration/i, 'You can exclude an auto-configuration with @SpringBootApplication(exclude = ...) or the spring.autoconfigure.exclude property. Exclude it only when you understand which default beans you are replacing.'],
  [/debug auto-configuration|auto-configuration report/i, 'Run the application with --debug or set debug=true. Spring Boot prints a condition evaluation report showing which auto-configurations matched, did not match, and why.'],
  [/SpringBootApplication contain/i, '@SpringBootApplication combines @SpringBootConfiguration, @EnableAutoConfiguration, and @ComponentScan. Together they mark the main configuration class, enable conditional setup, and scan the application package.'],
  [/difference between @Configuration, @ComponentScan, and @EnableAutoConfiguration/i, '@Configuration declares a source of bean definitions. @ComponentScan searches packages for component classes. @EnableAutoConfiguration imports Boot’s conditional configuration based on the classpath and settings.'],
  [/difference between @Component, @Service, @Repository, and @Controller/i, 'All four are component stereotypes detected during scanning. @Component is general, @Service represents business logic, @Repository represents persistence and translates database exceptions, and @Controller handles web requests.'],
  [/Controller and @RestController/i, '@RestController combines @Controller and @ResponseBody, so handler results are written directly as JSON or another response body. A normal @Controller usually returns a view name unless a method uses @ResponseBody.'],
  [/difference between @Bean and @Component/i, '@Component is placed on a class discovered by component scanning. @Bean is placed on a method inside configuration and is useful when creating a third-party class or when construction needs custom code.'],
  [/purpose of @Configuration/i, '@Configuration marks a class as a source of bean definitions. Methods annotated with @Bean are registered in the ApplicationContext and can receive injected dependencies.'],
  [/purpose of @Value/i, '@Value injects one property or expression into a field, constructor parameter, or method parameter. It is convenient for a small number of values, but grouped settings are usually clearer with @ConfigurationProperties.'],
  [/purpose of @ConfigurationProperties/i, '@ConfigurationProperties binds a group of related configuration properties to a typed Java class. It supports structured settings, relaxed names, validation, and easier testing.'],
  [/difference between @Value and @ConfigurationProperties/i, '@Value is concise for individual values. @ConfigurationProperties is better for a related group of settings because it provides a typed object, clear prefixes, and validation.'],
  [/purpose of @Profile/i, '@Profile limits a bean or configuration class to selected environments such as dev, test, or prod. The active profile decides which definitions are loaded.'],
  [/What is dependency injection/i, 'Dependency injection is a design technique where an object receives the objects it needs instead of creating them itself. Spring’s container creates the dependencies and supplies them to the object.'],
  [/different types of dependency injection/i, 'The common types are constructor injection, setter injection, and field injection. Constructor injection is normally preferred because required dependencies are explicit and the object can be immutable.'],
  [/constructor injection recommended/i, 'Constructor injection makes required dependencies visible, supports final fields, prevents partially initialized objects, and makes unit testing simple because dependencies can be passed directly.'],
  [/constructor, setter, and field injection/i, 'Constructor injection is best for required dependencies. Setter injection suits optional or changeable dependencies. Field injection is short but hides dependencies and makes plain unit testing harder, so it is generally avoided.'],
  [/What is autowiring/i, 'Autowiring is Spring’s process of finding a bean that matches a dependency and injecting it automatically. Spring can match by type and use @Qualifier or @Primary when more than one candidate exists.'],
  [/How does @Autowired work|single constructor/i, '@Autowired asks Spring to resolve and inject a dependency. Since Spring 4.3, a class with one constructor does not need @Autowired on that constructor; Spring uses it automatically.'],
  [/Qualifier and @Primary/i, '@Primary marks the default bean when several candidates have the same type. @Qualifier selects a specific named or qualified bean at an injection point.'],
  [/multiple beans of the same type/i, 'Spring reports an ambiguity error unless one bean is marked @Primary, the injection point uses @Qualifier, or the application injects a collection or map of all matching beans.'],
  [/different bean scopes|default bean scope/i, 'Common scopes are singleton, prototype, request, session, application, and websocket. Singleton is the default, meaning one bean instance is created per ApplicationContext.'],
  [/lifecycle of a Spring bean/i, 'Spring creates the bean, injects dependencies, applies post-processors, calls initialization callbacks, and makes it available. During context shutdown it calls destruction callbacks for beans that support them.'],
  [/PostConstruct and @PreDestroy/i, '@PostConstruct runs after dependency injection and is useful for initialization. @PreDestroy runs before bean destruction and is useful for releasing resources.'],
  [/circular dependency/i, 'A circular dependency occurs when bean A needs bean B while bean B also needs bean A. Constructor cycles usually fail fast because neither object can be created first.'],
  [/resolve circular dependencies/i, 'Prefer redesigning the classes so responsibilities are separated. If the relationship is genuinely optional, setter or lazy injection can help, but using it only to hide a design problem is not recommended.'],
  [/create a REST API/i, 'Create a class with @RestController, map methods with @GetMapping, @PostMapping, and related annotations, accept input with @RequestBody or parameters, and return a domain object or ResponseEntity.'],
  [/RequestMapping and specialized/i, '@RequestMapping is the general mapping annotation and can specify path and HTTP method. @GetMapping, @PostMapping, @PutMapping, @PatchMapping, and @DeleteMapping are shorter, clearer specialized forms.'],
  [/PathVariable and @RequestParam/i, '@PathVariable reads a value from the URL path, such as /users/42. @RequestParam reads a query parameter, such as /users?page=2.'],
  [/purpose of @RequestBody/i, '@RequestBody tells Spring to read the HTTP request body and convert it, commonly from JSON, into a Java object using an HttpMessageConverter.'],
  [/purpose of @ResponseBody/i, '@ResponseBody tells Spring to write a method’s return value to the HTTP response body. @RestController applies this behaviour to all handler methods by default.'],
  [/What is ResponseEntity/i, 'ResponseEntity represents the complete HTTP response, including body, status code, and headers. It is useful when an endpoint must control the response precisely.'],
  [/different HTTP status codes/i, 'Return ResponseEntity.status(...), use ResponseEntity.ok(), created(), noContent(), or annotate an exception and handler with @ResponseStatus. Choose codes that describe the result clearly.'],
  [/validate request data|@Valid and @Validated/i, 'Add the validation starter, place constraints such as @NotBlank or @Size on a request DTO, and use @Valid in the controller. @Validated also supports validation groups and method-level validation.'],
  [/custom validation annotations/i, 'Create an annotation with @Constraint, implement ConstraintValidator, and return false when the value is invalid. Add a clear message and apply the annotation to the DTO field or class.'],
  [/global exceptions|ControllerAdvice and @ExceptionHandler/i, '@RestControllerAdvice defines handlers shared by controllers. @ExceptionHandler maps an exception to a consistent response, so controllers do not repeat try-catch code.'],
  [/standard error-response structure/i, 'Use a stable response containing fields such as timestamp, status, error code, message, path, and validation details. Avoid exposing stack traces or internal database information to clients.'],
  [/API versioning/i, 'Common choices are a version in the path such as /api/v1/users, a request header, or a media type. Pick one strategy and document it consistently for clients.'],
  [/pagination and sorting/i, 'Accept page, size, and sort parameters, validate their limits, and return a Page or a custom response containing items and paging metadata. Spring Data Pageable can bind these values automatically.'],
  [/enable CORS/i, 'Configure CORS with @CrossOrigin for a small case or a WebMvcConfigurer or Spring Security configuration for application-wide rules. Allow only trusted origins and required methods.'],
  [/content negotiation/i, 'Content negotiation lets a client and server agree on a response representation such as JSON or XML. Spring uses request headers, URL patterns, and configured converters to choose the representation.'],
  [/convert Java objects to JSON|Jackson serialization/i, 'Spring Boot auto-configures Jackson when it is on the classpath. ObjectMapper converts Java objects to JSON and JSON request bodies back to Java objects; annotations or a configured ObjectMapper customize the process.'],
  [/file uploads and downloads/i, 'Accept uploads as MultipartFile and validate size, type, and filename. For downloads, return a Resource or byte stream with suitable content type and Content-Disposition headers. Store files outside the application package.'],
  [/properties and application.yml/i, 'Both formats define configuration. Properties uses key-value lines, while YAML represents nested values with indentation. Choose one style consistently and avoid duplicate keys across both files.'],
  [/externalized configuration|property-source precedence/i, 'Externalized configuration keeps environment values outside compiled code. Spring Boot combines sources such as command-line arguments, environment variables, profile files, and application files; higher-precedence sources override lower ones.'],
  [/environment-specific|profiles work|activate a profile/i, 'Use profile files such as application-dev.yml and application-prod.yml. Activate one with spring.profiles.active, an environment variable, or a command-line option, and keep secrets outside source control.'],
  [/read environment variables/i, 'Use placeholders such as ${DATABASE_URL}, @Value, or @ConfigurationProperties. Define a safe default only when it is appropriate and fail fast for required production values.'],
  [/secure passwords and sensitive/i, 'Do not commit passwords or tokens. Use environment variables, a secret manager, or platform secret storage, restrict access, rotate secrets, and ensure logs never print them.'],
  [/custom configuration properties|validate configuration properties/i, 'Create a class with @ConfigurationProperties and enable scanning, then add Bean Validation annotations when needed. Validation at startup catches missing or invalid settings before traffic reaches the application.'],
  [/What is Spring Data JPA/i, 'Spring Data JPA is an abstraction that creates repository implementations for the JPA standard. It reduces data-access boilerplate while allowing JPQL, specifications, and native queries when needed.'],
  [/different from Hibernate/i, 'JPA is a standard API, Hibernate is a popular JPA implementation, and Spring Data JPA is a repository abstraction built on top of JPA. They solve different layers of the persistence problem.'],
  [/CrudRepository and JpaRepository/i, 'CrudRepository provides basic CRUD operations. JpaRepository adds JPA-oriented methods such as flush and batch operations and also includes paging and sorting through its repository hierarchy.'],
  [/derived query methods/i, 'Spring Data parses a repository method name such as findByEmailAndStatus and builds a query from its parts. This is convenient for simple queries; use @Query for complex logic.'],
  [/purpose of @Query/i, '@Query lets you declare JPQL or native SQL directly on a repository method. It is useful when a derived method name would be unclear or cannot express the required query.'],
  [/JPQL and native SQL/i, 'JPQL uses entity and field names and is portable across databases. Native SQL uses database tables and columns, so it can use vendor features but is less portable.'],
  [/save\(\) and saveAndFlush/i, 'save() registers the entity for persistence but the SQL may wait until flush or transaction commit. saveAndFlush() explicitly flushes the persistence context immediately after saving.'],
  [/entity lifecycle/i, 'An entity can be transient, managed, detached, or removed. A managed entity is tracked by the persistence context, so changes can be written automatically during flush.'],
  [/FetchType\.LAZY and FetchType\.EAGER/i, 'LAZY loads a relationship when it is accessed, while EAGER loads it immediately. LAZY is usually safer for performance because it avoids fetching data that the request does not need.'],
  [/N\+1 query problem|solve the N\+1/i, 'N+1 happens when one query loads parent rows and an additional query runs for each parent. Use fetch joins, EntityGraph, carefully designed DTO queries, or batch fetching, then verify the SQL.'],
  [/fetch join|EntityGraph and fetch join/i, 'A fetch join loads a relationship in a JPQL query. EntityGraph declares the fetch plan separately from the query. Both can solve N+1, but the best choice depends on whether the fetch plan is query-specific or reusable.'],
  [/first-level cache/i, 'The first-level cache belongs to one persistence context or EntityManager. Within a transaction, repeated requests for the same entity can reuse the managed instance without another database query.'],
  [/second-level cache/i, 'The second-level cache is shared by sessions through a configured cache provider. It can reduce database reads across transactions, but invalidation and stale-data rules must be understood.'],
  [/dirty checking/i, 'Hibernate keeps a snapshot of managed entities. During flush it compares the current state with that snapshot and generates update SQL only when a tracked value changed.'],
  [/cascading/i, 'Cascading propagates an entity operation such as persist, merge, or remove from a parent to related entities. Use only the cascade types that match the ownership and lifecycle rules.'],
  [/orphan removal|CascadeType\.REMOVE/i, 'orphanRemoval deletes a child that is removed from the parent relationship. CascadeType.REMOVE deletes children when the parent is deleted. They are related but are triggered by different actions.'],
  [/optimistic locking|@Version/i, 'Optimistic locking assumes conflicts are uncommon. A @Version column changes on each update; if another transaction changed the row first, the update affects zero rows and Hibernate reports an optimistic-lock exception.'],
  [/pessimistic locking/i, 'Pessimistic locking asks the database to lock selected rows while a transaction works with them. It can prevent concurrent changes but may reduce throughput and cause blocking.'],
  [/pagination using Spring Data JPA/i, 'Accept a Pageable parameter and return Page<T> or Slice<T> from the repository. Add a stable sort, enforce reasonable page sizes, and remember that large offsets can become expensive.'],
  [/batch inserts and updates|slow database queries/i, 'Use JDBC batching settings, flush and clear in batches, avoid unnecessary entity loading, inspect generated SQL, and use database execution plans. Measure before and after the change.'],
  [/transaction management/i, 'A transaction groups database operations into one unit of work. Spring starts, commits, or rolls back the transaction through a transaction manager, usually around a service method.'],
  [/@Transactional work internally|private methods|self-invocation/i, '@Transactional is usually applied through a Spring proxy. Calls coming through the proxy receive transaction behaviour; private methods and calls from one method to another in the same object bypass that proxy.'],
  [/propagation types|default propagation/i, 'Propagation defines how a method joins or creates a transaction. REQUIRED is the default: it joins an existing transaction or creates one when none exists. Other modes include REQUIRES_NEW, SUPPORTS, and NESTED.'],
  [/isolation levels/i, 'Isolation controls what one transaction can see from another. Common levels are READ_UNCOMMITTED, READ_COMMITTED, REPEATABLE_READ, and SERIALIZABLE; the database determines the usual default.'],
  [/rollback behavior|checked and unchecked|rollback for checked/i, 'By default, Spring rolls back for unchecked RuntimeException and Error, not checked exceptions. Use rollbackFor on @Transactional when a checked exception must also trigger rollback.'],
  [/read-only transaction/i, 'A read-only transaction expresses that the code should not modify data. It can allow optimizations, but it is not a universal guarantee that the database will reject writes.'],
  [/distributed transaction|across microservices/i, 'A distributed transaction spans multiple resources or services. Prefer local transactions with events and patterns such as Saga or Outbox when possible; two-phase commit adds coordination and operational complexity.'],
  [/Spring Security work/i, 'Spring Security uses filters to inspect requests, authenticate users, create a security context, and authorize access. Spring Boot provides the dependencies and a convenient configuration entry point.'],
  [/authentication and authorization/i, 'Authentication answers “Who are you?” Authorization answers “What are you allowed to do?” A secure application performs both checks before protected work.'],
  [/filter chain|SecurityFilterChain/i, 'The filter chain is an ordered set of servlet filters that handles security concerns such as credentials, sessions, CSRF, and authorization. SecurityFilterChain is the bean used to configure those rules.'],
  [/endpoint authorization/i, 'Configure request rules in SecurityFilterChain using requestMatchers and authenticated, hasRole, or hasAuthority. Put specific rules before broad fallback rules.'],
  [/roles and authorities/i, 'An authority is a permission string. A role is a conventionally named authority, often prefixed with ROLE_. Use roles for broad groups and authorities for fine-grained permissions.'],
  [/JWT authentication|components of a JWT|validate and refresh JWT/i, 'A JWT contains a header, claims payload, and signature. The server verifies the signature and important claims such as issuer and expiry, then uses the subject or authorities for authorization. Short-lived access tokens and a controlled refresh-token flow reduce risk.'],
  [/OAuth 2\.0/i, 'OAuth 2.0 is an authorization framework that lets a client obtain limited access to a resource on behalf of a user or service. It defines flows and tokens; it is not itself a user-identity protocol.'],
  [/OpenID Connect/i, 'OpenID Connect adds an identity layer on top of OAuth 2.0. It provides an ID token and standard user claims so a client can verify who authenticated.'],
  [/CSRF|CORS/i, 'CSRF protects browser-based applications from forged state-changing requests. CORS controls which browser origins may call an API. They solve different problems and should not be treated as substitutes.'],
  [/method-level security|PreAuthorize|PostAuthorize/i, 'Enable method security and place authorization annotations on service methods. @PreAuthorize checks an expression before execution, while @PostAuthorize checks it after the method returns.'],
  [/store passwords securely|PasswordEncoder/i, 'Store a one-way adaptive hash, never plaintext or reversible encryption. PasswordEncoder implementations such as BCrypt or a delegating encoder salt and hash passwords and can support algorithm upgrades.'],
  [/Actuator endpoints/i, 'Actuator exposes operational endpoints such as health, info, metrics, loggers, and mappings. Expose only the endpoints needed by operators and protect them with authentication and network controls.'],
  [/Spring Security 6/i, 'Spring Security 6 uses the Jakarta namespace and requires modern Java and Spring versions. WebSecurityConfigurerAdapter is removed, so applications configure one or more SecurityFilterChain beans and use the updated authorization APIs.'],
  [/Spring Boot Actuator/i, 'Spring Boot Actuator adds production-focused endpoints for health, metrics, environment information, mappings, and other operational data. It helps teams monitor an application without writing every endpoint themselves.'],
  [/liveness and readiness/i, 'Liveness answers whether the process should be restarted. Readiness answers whether the instance should receive traffic. Keeping these checks separate helps orchestrators react correctly during startup and failure.'],
  [/Micrometer|application metrics|Prometheus and Grafana/i, 'Micrometer provides a vendor-neutral metrics API used by Spring Boot. Prometheus can scrape exported metrics, while Grafana visualizes them and supports dashboards and alerts.'],
  [/monitor JVM memory and garbage collection|database connection pools/i, 'Expose Micrometer and Actuator metrics, then watch heap usage, GC pauses, thread counts, active connections, idle connections, and acquisition time. Alerts should focus on sustained trends and user impact.'],
  [/logging framework|SLF4J/i, 'Spring Boot uses SLF4J as the logging facade with Logback as the default implementation. SLF4J lets application code use a stable API while the underlying logging implementation can change.'],
  [/logging levels|separate logging/i, 'Set levels with properties such as logging.level.org.springframework.web=INFO and use profile-specific configuration for different environments. Keep production logs useful without enabling verbose DEBUG globally.'],
  [/correlation ID|downstream services/i, 'Create or accept a request ID at the edge, put it in the logging context, return it in the response when appropriate, and forward it in outbound headers. Clear context when a thread is reused.'],
  [/log HTTP requests and responses|mask sensitive/i, 'Use a filter or observability library and log method, path, status, duration, and a safe request ID. Never log passwords, tokens, cookies, or unrestricted personal data; mask or omit sensitive fields.'],
  [/structured logging|JSON logging/i, 'Structured logging writes fields such as timestamp, level, service, trace ID, route, and error type in a machine-readable format such as JSON. It makes searching and aggregation more reliable than parsing prose messages.'],
  [/caching|Cacheable|CachePut|CacheEvict|Redis/i, 'Enable caching with @EnableCaching. @Cacheable reads or stores a method result, @CachePut always runs the method and updates the cache, and @CacheEvict removes entries. Redis is a common shared provider for distributed applications; define keys, TTLs, and consistency rules carefully.'],
  [/cache stampede|cache consistency/i, 'A cache stampede occurs when many requests regenerate the same expired value at once. Use TTL jitter, locking, request coalescing, or stale-while-revalidate. Update or evict related entries when the source data changes.'],
  [/performance|connection pooling|HikariCP|thread pool|memory leaks|high CPU|high memory|slow API|thread-pool exhaustion|thread dumps|heap dumps|graceful shutdown|request timeouts|large request|startup time|connection exhaustion|production issues/i, 'Start with evidence from metrics, logs, traces, thread dumps, heap dumps, database plans, and connection-pool statistics. Fix the largest measured bottleneck, set safe limits and timeouts, test the change under realistic load, and document the result. Avoid guessing or increasing every pool size because that can move the bottleneck elsewhere.'],
  [/major features of Spring Boot 3|minimum Java version|Spring Boot 2 and Spring Boot 3|javax to jakarta|migrating to Spring Boot 3|native images|GraalVM|observability improvements|security changes|2-to-3 migration/i, 'Spring Boot 3 is based on Spring Framework 6, requires Java 17 or newer, uses Jakarta namespaces, improves observability, and supports GraalVM native images. Migration normally requires updating dependencies, changing javax imports to jakarta, checking security configuration, testing third-party libraries, and reviewing removed APIs.']
];

const TOPIC_CONTEXT: Record<string, string> = {
  'spring-boot-fundamentals': 'Spring Boot fundamentals explain how a Java application starts and how Spring manages its components.',
  'spring-boot-auto-configuration': 'Spring Boot auto-configuration uses the classpath and conditions to provide sensible defaults without hiding your ability to customize them.',
  'spring-boot-annotations': 'Spring Boot annotations describe configuration, component discovery, web endpoints, and application properties in a concise way.',
  'spring-boot-dependency-injection': 'Dependency injection is the foundation of Spring Boot applications because the container creates objects and connects their dependencies.',
  'spring-boot-rest-api': 'REST API design in Spring Boot connects HTTP requests to controller, service, and persistence layers.',
  'spring-boot-configuration': 'Spring Boot configuration separates environment-specific values from application code and makes deployment safer.',
  'spring-boot-data-jpa': 'Spring Data JPA helps Java applications work with relational data through repositories, entities, and transactions.',
  'spring-boot-transactions': 'Transaction management protects data consistency by grouping related database operations into one unit of work.',
  'spring-boot-security': 'Spring Security protects Spring Boot applications through authentication, authorization, filters, and secure credential handling.',
  'spring-boot-actuator': 'Actuator and monitoring make application health, metrics, and operational behaviour visible to development and operations teams.',
  'spring-boot-logging': 'Logging and observability help developers understand application behaviour and investigate failures safely.',
  'spring-boot-caching': 'Caching improves response time by reusing frequently requested data, but it requires clear expiry and consistency rules.',
  'spring-boot-production-performance': 'Production performance work should be guided by measurements from the JVM, database, network, and application metrics.',
  'spring-boot-3': 'Spring Boot 3 modernizes the Spring platform with Java 17, Jakarta EE APIs, improved observability, and native-image support.'
};

const answerFor = (text: string, topicId: string): string => {
  const match = ANSWER_RULES.find(([pattern]) => pattern.test(text));
  return match?.[1] ?? `${TOPIC_CONTEXT[topicId] ?? 'This Spring Boot concept is used in production Java applications.'} Start with the definition, understand which problem it solves, and then apply it in a small example. In an interview, explain the normal use, the main trade-off, and one practical mistake to avoid.`;
};

const question = (id: number, topicId: string, text: string, difficulty: InterviewQuestion['difficulty'], tags: readonly string[]): InterviewQuestion => ({ id, topicId, question: text, answer: answerFor(text, topicId), difficulty, tags });

